VALUES ((SELECT id FROM macro_core.series WHERE key = 'fedwatch_next_fomc'), DATE '2026-07-31', NULL, '~66% hike / ~34% hold, cuts zero. The arc: ~82% (Jul 23) → 77% (Jul 29 pre-decision) → 63% (Jul 30) → ~66% (Aug 2). The 2Y at 4.28% sits ~62 bps above the funds midpoint, so the curve is still pricing a hike, not a cut. [growbeansprout FedWatch mirror, as-of Aug 2 - Monday''s 6% crude collapse is not yet in these odds; re-check same-day]', 2, 'CME FedWatch via aggregator (search agent) (migrated from Weekly Market Journal 2026-W32)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-03T00:00:00Z')
