INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'geopolitical_state'), DATE '2026-07-31', NULL, 'Iran war at ~Day 156 (began Feb 28), and the state inverted twice in five days. The pause broke Jul 29 (Iran struck US forces; the US and Saudi Arabia hit Iran-backed militias in Iraq; Houthi drones hit Aramco at Jizan and Yanbu). Then Aug 2: Trump cancelled a planned strike and announced agreed "perimeters" of a deal including the "immediate, complete and total" reopening of Hormuz, with talks resuming Aug 3 under Qatari and Pakistani mediation. Iran''s Mehr agency called the account "simply a new lie." This is a headline, not a signed agreement; the ~Aug 16 MoU expiry is now the ratification deadline.', 2, 'Wire and analysis coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W32)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-03T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
    display = EXCLUDED.display,
    tier = EXCLUDED.tier,
    source = EXCLUDED.source,
    released = EXCLUDED.released,
    note = EXCLUDED.note,
    extra = EXCLUDED.extra,
    observed_at = EXCLUDED.observed_at,
    received_at = EXCLUDED.received_at;
INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'geopolitical_state'), DATE '2026-08-14', NULL, 'Iran war at ~Day 170. The 60-day MoU expired Aug 16 with no deal - stalemate, not collapse: Iran conditions Hormuz reopening on unfrozen funds and disputes the ratification clock; Bessent threatens "unprecedented" economic-isolation measures; the naval blockade holds; tanker/port strikes continue (ADNOC tankers, Bab al-Mandeb double-tap). Red Sea attacks ongoing; PRC grey-zone pressure on Taiwan elevated.', 2, 'Wire and analysis coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W34)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-17T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
    display = EXCLUDED.display,
    tier = EXCLUDED.tier,
    source = EXCLUDED.source,
    released = EXCLUDED.released,
    note = EXCLUDED.note,
    extra = EXCLUDED.extra,
    observed_at = EXCLUDED.observed_at,
    received_at = EXCLUDED.received_at;
INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'geopolitical_state'), DATE '2026-08-21', NULL, 'Iran war at ~Day 177, and the escalation vector turned financial. Bessent promises the "toughest sanctions in history" and held a Monday Aug 24 press conference on "the greatest coordinated economic isolation in history"; Treasury sanctioned Hengli Petrochemical, its most significant action yet against China''s refining industry, putting Chinese buyers of Iranian crude explicitly in secondary-sanction scope. Beijing said it will not cooperate. Iranian crude repriced from a $3 discount to a $2 premium to Brent as teapot refiners stepped back. Hormuz remains largely closed (traffic a fraction of the pre-war ~130 ships/day). First genuine de-escalation signal of the war: Pezeshkian said Friday it would be better to end it now. Russia-Ukraine stalled on territory and monitoring; PRC grey-zone pressure on Taiwan elevated, with Taipei announcing a ~$40B defense package.', 2, 'Wire and analysis coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W35)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-24T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
    display = EXCLUDED.display,
    tier = EXCLUDED.tier,
    source = EXCLUDED.source,
    released = EXCLUDED.released,
    note = EXCLUDED.note,
    extra = EXCLUDED.extra,
    observed_at = EXCLUDED.observed_at,
    received_at = EXCLUDED.received_at;
INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'geopolitical_state'), DATE '2026-08-28', NULL, 'Iran and Hormuz remain the dominant cross-asset flashpoint. Financial sanctions expanded even as reopening hopes cut oil''s premium, then US strikes on Iranian launchers Aug 30 restored Monday gap risk; Russia-Ukraine and Taiwan tensions remain active.', 2, 'Wire and analysis coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W36)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-31T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
    display = EXCLUDED.display,
    tier = EXCLUDED.tier,
    source = EXCLUDED.source,
    released = EXCLUDED.released,
