INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'geopolitical_state'), DATE '2026-09-04', NULL, 'The Iran war is past its air campaign but the Hormuz chokepoint is now the active theatre — US strikes on three Iranian tankers Sep 5–6, an Iranian ballistic missile fired toward US carriers, a declared maritime exclusion zone announced Sep 7, and Houthi missile and drone strikes that suspended some Saudi Aramco operations Sep 8. Israel–Hezbollah sits under a fragile ceasefire; Ukraine has a capital-strike pause and an unformalised Sep 5–8 halt but no ceasefire.', 2, 'Wire and analysis coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W37)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-09-09T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
    display = EXCLUDED.display,
