INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'geopolitical_state'), DATE '2026-09-11', NULL, 'The US–Iran war is now a tanker-for-tanker campaign: the US sank five Iranian tankers, Iran declared strikes on 10 ships and a US base in Jordan, and Saudi output fell to 6.24 mb/d, the lowest since 1990. Oman''s Sep 14 Iran–GCC Hormuz meeting was postponed on Sep 13 with no new date, and Trump has said the war ends only after the November midterms. Russia–Ukraine''s Sep 5–8 pause ended with no ceasefire.', 2, 'Wire and analysis coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W38)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-09-14T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
