INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'geopolitical_state'), DATE '2026-09-18', NULL, 'the US/Israel–Iran war is at roughly day 203 and is now a tanker war around a Strait of Hormuz whose traffic remains well below normal. Drone strikes from Iraqi territory hit Saudi Arabia''s East-West pipeline on Sep 10–11 and Houthi missiles and drones struck Saudi targets again on Sep 19; Aramco is bypassing the damaged section and guiding to full capacity in about six weeks. Russia–Ukraine grinds on, and the Israel–Lebanon ceasefire is holding but strained.', 2, 'Wire and analysis coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W39)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-09-21T00:00:00Z')
