VALUES ((SELECT id FROM macro_core.series WHERE key = 'state_street_equity_allocation'), DATE '2026-07-31', 58.0, '58.0% (Jul) (no new release; +1.42 pp MoM)', 2, 'State Street Investor Indicators, July 2026 data month', NULL, 'July 2026 data month, published August 2026 (mid-month; covered by Seoul Economic Daily 2026-08-17 and WealthBriefing). Latest official print as of the 2026-09-04 as-of date - the August data month release lands mid-September, so this is repeated, not stale. Allocations: equities 58%, fixed income ex-bills 26%, cash 16%. Risk Appetite Index eased to 0.18 from 0.45 in June but stayed positive; equity overweight reported as most pronounced since mid-2007. Exact day-of-month release date not stated on the State Street page. released as written: 2026-08', '{"search_metric":"State Street institutional equity allocation"}'::jsonb, NULL, TIMESTAMPTZ '2026-09-09T00:00:00Z')
