VALUES ((SELECT id FROM macro_core.series WHERE key = 'state_street_equity_allocation'), DATE '2026-08-31', 57.4, '57.4% (Aug data, released Sep 9) (−0.13 pp MoM per State Street); FI 24.9%, cash 17.6%', 1, 'State Street Investor Indicators, August 2026 data month (released Sep 9)', DATE '2026-09-09', 'Official release; publishedDate 2026-09-09 in page metadata. Prior journal''s July 58.0% was a rounded figure; State Street states equities fell ~13 bps in August, so a naive 58.0 to 57.4 diff (−0.6 pp) overstates the move. Risk appetite cross-checked via State Street LinkedIn post.', '{"search_metric":"State Street institutional equity allocation"}'::jsonb, NULL, TIMESTAMPTZ '2026-09-14T00:00:00Z')
