INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'tariff_state'), DATE '2026-07-31', NULL, 'statutory weighted-average rate ~11.1% in force (~11.8% once every scheduled tariff lands); realized effective rate 6.6-7.2%, the highest since 1969. Section 122 expired Jul 24 into the Section 301 forced-labor regime at 10-12.5% across ~60 partners. Section 232 pharma at 100% took effect Jul 31 for Annex III companies (Sep 29 for everyone else; thirteen Annex II MFN signatories exempt to Jan 20, 2029). Section 338 lands Aug 19: a 50% duty on Canadian alcohol, dairy and motor vehicles, the first presidential use of Section 338 ever. IEEPA authority remains struck down since Feb 20.', 2, 'Tariff tracker coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W32)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-03T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
