INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'tariff_state'), DATE '2026-08-14', NULL, 'statutory weighted-average rate ~11.0% in force (headed ~11.8% by year-end under current law). Section 232 polysilicon at 15% took effect Aug 6; Section 338''s 50% duty on Canadian alcohol, dairy and motor vehicles lands Aug 19; the Section 301 forced-labor regime (~60 partners) continues.', 2, 'Tariff tracker coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W34)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-17T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
