INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'tariff_state'), DATE '2026-08-21', NULL, 'measured effective rate ~7.1% (June 2026) on a post-IEEPA footing — a 10% Section 122 global baseline (whose Jul 24 expiry leaves the statutory footing contested), Section 232 sectorals at 25-50%, and Section 301 China duties. Section 338''s 50% duties on Canadian vehicles, dairy and alcohol took effect Aug 22 after a three-day suspension and the collapse of talks; Canada retaliates dollar-for-dollar from Sep 8. Nonfuel import prices are +4.5% y/y, the fastest since June 2022.', 2, 'Tariff tracker coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W35)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-24T00:00:00Z')
