INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'tariff_state'), DATE '2026-08-28', NULL, '10% Section 301 duties replaced the expired Section 122 surcharge; Section 232 sectorals remain; 50% Section 338 duties on selected Canadian goods took effect Aug 22, with Canadian counter-tariffs due Sep 8.', 2, 'Tariff tracker coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W36)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-08-31T00:00:00Z')
