INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'tariff_state'), DATE '2026-09-04', NULL, 'Post-IEEPA regime, now a live trade war with Canada. Section 301 covers 60 partners at 10% or 12.5% (Brazil 37.5%), Section 232 holds steel and aluminium at 50%, Section 338 adds 50% on Canadian autos, dairy and alcohol, and drone duties of up to 100% took effect Sep 3. Canada''s dollar-for-dollar retaliation on 700+ US products at 15–50% took effect Sep 8, and Lutnick has signalled a broader Section 232 semiconductor phase reaching servers and finished systems.', 2, 'Tariff tracker coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W37)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-09-09T00:00:00Z')
ON CONFLICT (series_id, asof) DO UPDATE SET
    value = EXCLUDED.value,
    display = EXCLUDED.display,
