INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'tariff_state'), DATE '2026-09-11', NULL, 'Post-IEEPA regime of Section 232 sectoral tariffs and Section 301 duties at 10%–12.5%, plus an escalating Canada fight: 50% Section 338 duties since Aug 22 with scope modified Sep 15, Canada''s retaliation on 700+ US goods since Sep 8, and US import bans on Canadian alcohol, dairy and large motorcycles effective Sep 29. US–China talks on a $30B reciprocal cut run ahead of a Trump–Xi meeting Sep 24.', 2, 'Tariff tracker coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W38)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-09-14T00:00:00Z')
