INSERT INTO macro_core.observation (series_id, asof, value, display, tier, source, released, note, extra, observed_at, received_at)
VALUES ((SELECT id FROM macro_core.series WHERE key = 'tariff_state'), DATE '2026-09-18', NULL, 'unchanged and still escalating — layered Section 232/301/338 regime, 100% on patented drugs and biologics (15% EU/Japan/Korea/Switzerland, 10% UK), 25% autos and parts, 10–50% steel and aluminium, 100% maritime cargo equipment, 25% on Brazil, and Canadian 15/25/50% retaliation live since Sep 8. The dated item inside 30 days is the 100% pharma tariff extending to all non-Annex-III manufacturers on Sep 29.', 2, 'Tariff tracker coverage (asserted, search agent) (migrated from Weekly Market Journal 2026-W39)', NULL, NULL, '{}'::jsonb, NULL, TIMESTAMPTZ '2026-09-21T00:00:00Z')
